const sumLabourForMashRuns = `-- name: SumLabourForMashRuns :one
SELECT COALESCE(SUM(hours), 0)::double precision AS hours
FROM labour_entries WHERE mash_run_id = ANY($1::uuid[])
`

func (q *Queries) SumLabourForMashRuns(ctx context.Context, ids []uuid.UUID) (float64, error) {
	row := q.db.QueryRow(ctx, sumLabourForMashRuns, ids)
	var hours float64
	err := row.Scan(&hours)
	return hours, err
}

const valueBulkForWIP = `-- name: ValueBulkForWIP :many
SELECT bc.id, bc.name, bc.kind, bc.current_volume_l, bc.current_abv_pct,
       bc.current_laa, bc.possession
FROM bulk_containers bc
WHERE NOT bc.archived
  AND bc.owner_customer_id IS NULL
  AND bc.current_laa > 0
ORDER BY bc.kind, bc.name
`

type ValueBulkForWIPRow struct {
	ID             uuid.UUID         `json:"id"`
	Name           string            `json:"name"`
	Kind           BulkContainerKind `json:"kind"`
	CurrentVolumeL float64           `json:"current_volume_l"`
	CurrentAbvPct  pgtype.Float8     `json:"current_abv_pct"`
	CurrentLaa     float64           `json:"current_laa"`
	Possession     BulkPossession    `json:"possession"`
}

// Everything still in bulk, which is what work in progress means for a
// distillery: alcohol made and not yet packaged. Barrels included — a
// cask maturing is the largest WIP a whisky distillery has.
//
// Owned stock only. Spirits held for a customer are on the B266 and not
// on the balance sheet (stage 176).
func (q *Queries) ValueBulkForWIP(ctx context.Context) ([]ValueBulkForWIPRow, error) {
	rows, err := q.db.Query(ctx, valueBulkForWIP)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ValueBulkForWIPRow{}
	for rows.Next() {
		var i ValueBulkForWIPRow
		if err := rows.Scan(
			&i.ID,
			&i.Name,
			&i.Kind,
			&i.CurrentVolumeL,
			&i.CurrentAbvPct,
			&i.CurrentLaa,
			&i.Possession,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const valuePackagedForFinishedGoods = `-- name: ValuePackagedForFinishedGoods :many
SELECT pi.id, pi.lot_code, pi.jurisdiction, pi.bottles_on_hand,
       pi.bottling_run_id, p.name AS product_name,
       p.bottle_size_ml, p.target_abv_pct
FROM packaged_inventory pi
JOIN products p ON p.id = pi.product_id
WHERE pi.bottles_on_hand > 0
  -- Owned stock only. A customer's bottles sitting in the warehouse are
  -- on the B266 and not on the balance sheet — the same rule the bulk
  -- side follows (stage 176), now that a lot knows whose it is.
  AND pi.owner_customer_id IS NULL
ORDER BY p.name, pi.lot_code
`

type ValuePackagedForFinishedGoodsRow struct {
	ID            uuid.UUID     `json:"id"`
	LotCode       string        `json:"lot_code"`
	Jurisdiction  string        `json:"jurisdiction"`
	BottlesOnHand int32         `json:"bottles_on_hand"`
	BottlingRunID uuid.NullUUID `json:"bottling_run_id"`
	ProductName   string        `json:"product_name"`
	BottleSizeMl  int32         `json:"bottle_size_ml"`
	TargetAbvPct  float64       `json:"target_abv_pct"`
}

// Bottles on hand, with the run each came from so the cost that run
// carried can be applied. A lot with no run behind it (adopted stock)
// comes back with a NULL run and is reported as unvalued rather than
// valued at zero.
func (q *Queries) ValuePackagedForFinishedGoods(ctx context.Context) ([]ValuePackagedForFinishedGoodsRow, error) {
	rows, err := q.db.Query(ctx, valuePackagedForFinishedGoods)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ValuePackagedForFinishedGoodsRow{}
	for rows.Next() {
		var i ValuePackagedForFinishedGoodsRow
		if err := rows.Scan(
			&i.ID,
			&i.LotCode,
			&i.Jurisdiction,
			&i.BottlesOnHand,
			&i.BottlingRunID,
			&i.ProductName,
			&i.BottleSizeMl,
			&i.TargetAbvPct,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
